INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (618, 56, 4, 'Работы не было', 97, '{"prompt_user": "json:{\\"env_ok\\": false, \\"ok\\": false, \\"report\\": {}, \\"error\\": \\"Работы не было: в ветке подзадачи нет ни коммитов, ни правок. Похоже, агент ответил, не приступив к работе.\\"}", "continue_workflow": false, "transitions_before": [], "transitions_after": []}') ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (619, 56, 3, 'Снимок ветки до работы', 4, '{"tool_invoke": {"tool_name": "task_worktree_state", "inputs_map": {"subtask_id": "subtask_id"}, "outputs_map": {"done_mark": "work_mark_before"}}, "transitions_before": [], "transitions_after": []}') ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (620, 56, 3, 'Снимок ветки после работы', 7, '{"tool_invoke": {"tool_name": "task_worktree_state", "inputs_map": {"subtask_id": "subtask_id", "since": "work_mark_before"}, "outputs_map": {"done_changed": "work_changed", "done_has": "work_has"}}, "transitions_before": [], "transitions_after": [{"variable": "work_has", "operator": "==", "value": "no", "step_id": "618"}]}') ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

